typedef enum { STATE_MENU, STATE_PLAYING, STATE_GAMEOVER } GameState;

int main(void) {
    GameState state = STATE_PLAYING;
    int lives = 0;

    printf("MENU=%d PLAYING=%d GAMEOVER=%d\n", STATE_MENU, STATE_PLAYING, STATE_GAMEOVER);
    if (lives == 0) {
        state = STATE_GAMEOVER;
    }
    switch (state) {
        case STATE_MENU:     printf("show menu\n"); break;
        case STATE_PLAYING:  printf("run game\n"); break;
        case STATE_GAMEOVER: printf("show game over\n"); break;
    }
    return 0;
}

